  '#f-rows [data-field="${field}"] .ib')]
  .map(b => (b.getAttribute('aria-label') || '?').split(':')[0])`);
const popButtons = () => ev(`[...document.querySelectorAll('#fpop .ib')]
  .map(b => (b.getAttribute('aria-label') || '?').split(':')[0])`);
