/* ---- the entry popup ---- */
.iconbar {
  display: flex; align-items: center; flex-wrap: wrap; gap: .15rem;
  padding-bottom: .5rem; margin-bottom: .5rem; border-bottom: 1px solid var(--line);
}
.iconbar .spacer { flex: 1; }
/* The toggle row, under start and end: `24h` alone on an event, with stage, important and the
   estimate on a task. */
.flags { padding: .5rem 0 .2rem; margin: 0; border: 0; }
.flags .ib { position: relative; }
/* Stage and the estimate show their value as a badge on the icon's corner. Important has
   nothing to put in one and lights instead, the way `24h` does. */
.badge {
  position: absolute; right: .25rem; bottom: .25rem;
  min-width: .95rem; padding: 0 .1rem;
  font-size: .58rem; font-weight: 700; line-height: .95rem; text-align: center;
  color: var(--bg); background: var(--fg); border-radius: 999px;
}
.badge:empty { min-width: .55rem; height: .55rem; line-height: .55rem; }
.badge.wide { min-width: 1.15rem; }
.row2 { display: flex; gap: .6rem; }
.row2 label { flex: 1; }
